    #strixpro-wrap .sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
    }
    #strixpro-wrap .vid-control {
    cursor: pointer;
    width: 5em;
    height: 5em;
    background: none;
    border: none;
    box-shadow: none;
    position: absolute;
    left: 19%;
    top: 76%;
    transform: translate(0%, -50%);
    transition: all 0.3s ease-out;
    z-index: 2
    }
    #strixpro-wrap .vid-control:focus-visible {
      /* remove default focus style */
      outline: none;
      /* custom focus styles */
      box-shadow: 0 0 2px 2px #ff53d4;
      color: lime;
    }
    #strixpro-wrap .vid-control img,
    #strixpro-wrap .vid-control svg {
    width: 100%;
    height: 100%
    }

    #strixpro-wrap .vid-control .play_s {
    display: none
    }

    #strixpro-wrap .vid-control.hd-active .play_s {
    display: block
    }

    #strixpro-wrap .vid-control.hd-active .pause {
    display: none
    }
    #strixpro-wrap .video .vid-control{
    bottom: 5%;
    right: 5%;
    cursor: pointer;
    }
    #strixpro-wrap .video .vid-control svg{  
    width: 100%;
    height: 100%;
    }
    @media screen and (max-width: 1023px){
    #strixpro-wrap .video .vid-control{
    bottom: 5%;
    right: 5%;
    }
    }
    @media screen and (max-width: 768px){
    #strixpro-wrap .video .vid-control{
    bottom: 5%;
    right: 5%;
    }
}

#strixpro-wrap #ROG-Strix-Arion-04 .maintitle .pd_img_area{
    position: relative;
}
#strixpro-wrap #ROG-Strix-Arion-04 .maintitle .pd_img_area .pd_img_a{
    position: absolute;
    left: 50%;
    top: 0;
    transform: translate(-50%, 0%);
}
#strixpro-wrap #ROG-Strix-Arion-04 .maintitle .pd_img_area .pd_img_b{
    position: absolute;
    left: 50%;
    top: 0;
    transform: translate(-50%, 0%);
    opacity: 0;
}
#strixpro-wrap #ROG-Strix-Arion-04 .move_transition{
    -webkit-transition: all 1s ease;
    -moz-transition: all 1s ease;
    -o-transition: all 1s ease;
    transition: all 1s ease;
}
#strixpro-wrap #ROG-Strix-Arion-04 .maintitle .pd_img_area.pd_move .pd_img_b{
    left: 33%;
    opacity: 1;
}
#strixpro-wrap #ROG-Strix-Arion-04 .maintitle .pd_img_area.pd_move .pd_img_a{
    left: 68%;
}

