#strixpro-wrap #ROG-Strix-Arion-Embrace{
    background: #ddd;
    color: black;
    position: relative;
    overflow: hidden;
    padding: 2em 0;
    text-align: center;
}
#strixpro-wrap #ROG-Strix-Arion-Embrace .mainsize .maintitle{
    padding: 50px 18px;
}
